{"GUEST_LEAVE_REPLY","reg=military,elite",{"Copy, departing, thank you for the shelter","Copy, departing, thank you"}},
{"GUEST_LEAVE_REPLY","reg=outlaw,raider,gang,club,crime,prison",{"Heh, kicking me out? Fine, fine, I was getting bored anyway","Fine, I'm out, don't get sentimental"}},
